import React, { useEffect, useState } from 'react';
import { api, getTelegramUser } from '../api';
import { PlusCircleOutlined } from '@ant-design/icons';
import { Tabs, Table, Input, Button, Space, Typography, message, Tag, Card, Alert } from 'antd';

interface TopKeyword {
  keyword: string;
  count: number;
  avg_relevance: number;
  type: string;
}

interface SearchMessage {
  id: string;
  text: string;
  text_preview: string;
  created_at: string;
  sender_type: string;
}

interface ExcludedItem {
  id: number;
  word: string;
  hit_count: number;
}

interface ExtractedKeyword {
  word: string;
  relevance: number;
  type: string;
}

const Keywords: React.FC = () => {
  const [topKeywords, setTopKeywords] = useState<TopKeyword[]>([]);
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchMessage[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Admin controls
  const [excluded, setExcluded] = useState<ExcludedItem[]>([]);
  const [newExWord, setNewExWord] = useState('');
  const [promptText, setPromptText] = useState('');
  const [savingPrompt, setSavingPrompt] = useState(false);
  const [adminError, setAdminError] = useState<string | null>(null);

  // Test extraction
  const [testText, setTestText] = useState('');
  const [testKeywords, setTestKeywords] = useState<ExtractedKeyword[] | null>(null);
  const [testing, setTesting] = useState(false);

  const telegramUser = getTelegramUser();
  const requireTgId = (): string => {
    const id = telegramUser?.id?.toString();
    if (!id) throw new Error('Не найден Telegram ID');
    return id;
  };

  const loadTop = async () => {
    setLoading(true);
    setError(null);
    try {
      const resp = await api('/messages/keywords/top?limit=50', {
        method: 'GET',
        headers: {
          'X-Telegram-User-ID': requireTgId(),
        }
      });
      if (resp.status === 'success') {
        setTopKeywords(resp.keywords || []);
      }
    } catch (e: any) {
      setError(e?.message || 'Ошибка загрузки топа ключевых слов');
    } finally {
      setLoading(false);
    }
  };

  const addExclusionWord = async (word: string) => {
    const w = (word || '').trim().toLowerCase();
    if (!w) return;
    try {
      const tgId = requireTgId();
      const resp = await api('/admin/keywords/exclusions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Telegram-User-ID': tgId,
          ...(sessionStorage.getItem('token') ? { Authorization: `Bearer ${sessionStorage.getItem('token')}` } : {}),
        },
        body: JSON.stringify({ word: w })
      });
      if (resp?.status === 'success') {
        await loadAdminData();
        await loadTop();
        message.success(`Добавлено в исключения: ${w}`);
      }
    } catch (e) {
      // игнорируем для простоты
    }
  };

  const runSearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const resp = await api(`/messages/keywords/search?keyword=${encodeURIComponent(query.trim())}`, {
        method: 'GET',
        headers: {
          'X-Telegram-User-ID': requireTgId(),
        }
      });
      if (resp.status === 'success') {
        setResults(resp.messages || []);
      }
    } catch (e: any) {
      setError(e?.message || 'Ошибка поиска по ключевому слову');
    } finally {
      setLoading(false);
    }
  };

  const loadAdminData = async () => {
    try {
      setAdminError(null);
      const tgId = requireTgId();
      const auth = sessionStorage.getItem('token') ? { Authorization: `Bearer ${sessionStorage.getItem('token')}` } : {};
      const [ex, pr] = await Promise.all([
        api('/admin/keywords/exclusions', {
          method: 'GET',
          headers: {
            'X-Telegram-User-ID': tgId,
            ...auth,
          }
        }),
        api('/admin/keywords/prompt', {
          method: 'GET',
          headers: {
            'X-Telegram-User-ID': tgId,
            ...auth,
          }
        })
      ]);
      if (ex?.status === 'success') setExcluded(ex.items || []);
      if (pr?.status === 'success') setPromptText(pr.prompt || '');
    } catch (e: any) {
      setAdminError(e?.message || 'Ошибка загрузки админ-данных (нужна роль Архитектора)');
    }
  };

  const addExclusion = async () => {
    const w = newExWord.trim().toLowerCase();
    if (!w) return;
    try {
      setAdminError(null);
      const tgId = requireTgId();
      const resp = await api('/admin/keywords/exclusions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Telegram-User-ID': tgId,
          ...(sessionStorage.getItem('token') ? { Authorization: `Bearer ${sessionStorage.getItem('token')}` } : {}),
        },
        body: JSON.stringify({ word: w })
      });
      if (resp?.status === 'success') {
        setNewExWord('');
        await loadAdminData();
        await loadTop();
        message.success(`Добавлено в исключения: ${w}`);
      }
    } catch (e: any) {
      setAdminError(e?.message || 'Ошибка добавления исключения');
    }
  };

  const removeExclusion = async (id: number) => {
    try {
      setAdminError(null);
      const tgId = requireTgId();
      await api(`/admin/keywords/exclusions/${id}`, {
        method: 'DELETE',
        headers: {
          'X-Telegram-User-ID': tgId,
          ...(sessionStorage.getItem('token') ? { Authorization: `Bearer ${sessionStorage.getItem('token')}` } : {}),
        }
      });
      await loadAdminData();
      await loadTop();
    } catch (e: any) {
      setAdminError(e?.message || 'Ошибка удаления исключения');
    }
  };

  const savePrompt = async () => {
    try {
      setSavingPrompt(true);
      setAdminError(null);
      const tgId = requireTgId();
      if (!promptText.trim()) {
        const ok = window.confirm('Сохранить пустой промпт? Будет использован дефолтный.');
        if (!ok) { setSavingPrompt(false); return; }
      }
      await api('/admin/keywords/prompt', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Telegram-User-ID': tgId,
          ...(sessionStorage.getItem('token') ? { Authorization: `Bearer ${sessionStorage.getItem('token')}` } : {}),
        },
        body: JSON.stringify({ prompt: promptText })
      });
      message.success('Промпт сохранён');
    } catch (e: any) {
      setAdminError(e?.message || 'Ошибка сохранения промпта');
    } finally {
      setSavingPrompt(false);
    }
  };

  const testExtraction = async () => {
    if (!testText.trim()) return;
    try {
      setTesting(true);
      const tgId = requireTgId();
      const resp = await api('/messages/keywords/extract-test', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Telegram-User-ID': tgId,
          ...(sessionStorage.getItem('token') ? { Authorization: `Bearer ${sessionStorage.getItem('token')}` } : {}),
        },
        body: JSON.stringify({ text: testText })
      });
      if (resp?.status === 'success') setTestKeywords(resp.keywords || []);
    } catch (e: any) {
      setAdminError(e?.message || 'Ошибка тестирования извлечения');
    } finally {
      setTesting(false);
    }
  };

  useEffect(() => {
    try {
      loadTop();
      loadAdminData();
    } catch (e: any) {
      setError(e?.message || 'Ошибка инициализации (нет Telegram ID)');
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const topColumns = [
    { title: 'Ключевое слово', dataIndex: 'keyword', key: 'keyword' },
    { title: 'Тип', dataIndex: 'type', key: 'type', render: (t: string) => t ? <Tag>{t}</Tag> : '-' },
    { title: 'Кол-во', dataIndex: 'count', key: 'count', width: 120 },
    { title: 'Rel', dataIndex: 'avg_relevance', key: 'avg_relevance', width: 120, render: (v: number) => (v ?? 0).toFixed(2) },
    { title: 'Действия', key: 'actions', width: 120, render: (_: any, r: TopKeyword) => (
      <Button
        size="small"
        icon={<PlusCircleOutlined />}
        onClick={() => addExclusionWord(r.keyword)}
        disabled={excluded.some(e => e.word?.toLowerCase() === r.keyword?.toLowerCase())}
      >
        В исключения
      </Button>
    ) },
  ];

  const searchColumns = [
    { title: 'Дата', dataIndex: 'created_at', key: 'created_at', width: 200, render: (v: string) => new Date(v).toLocaleString('ru-RU') },
    { title: 'Отправитель', dataIndex: 'sender_type', key: 'sender_type', width: 130, render: (s: string) => s === 'user' ? 'Пользователь' : 'Бот' },
    { title: 'Текст', dataIndex: 'text_preview', key: 'text_preview', render: (_: any, r: SearchMessage) => r.text_preview || r.text },
    { title: 'ID', dataIndex: 'id', key: 'id', width: 180 },
  ];

  const exclColumns = [
    { title: 'Слово', dataIndex: 'word', key: 'word' },
    { title: 'Срабатываний', dataIndex: 'hit_count', key: 'hit_count', width: 160 },
    { title: 'Действия', key: 'actions', width: 140, render: (_: any, r: ExcludedItem) => (
      <Button danger size="small" onClick={() => removeExclusion(r.id)}>Удалить</Button>
    )},
  ];

  const testColumns = [
    { title: 'Слово', dataIndex: 'word', key: 'word' },
    { title: 'Тип', dataIndex: 'type', key: 'type', width: 140 },
    { title: 'Rel', dataIndex: 'relevance', key: 'relevance', width: 120, render: (v: number) => (v ?? 0).toFixed(2) },
  ];

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)', boxSizing: 'border-box', maxWidth: '100%' }}>
      <Typography.Title level={3} style={{ marginBottom: 'var(--sp-spacing-sm)' }}>Ключевые слова</Typography.Title>
      <Tabs
        defaultActiveKey="top"
        items={[
          {
            key: 'top',
            label: 'Топ',
            children: (
              <Card>
                {error && <Typography.Text type="danger">{error}</Typography.Text>}
                <Table
                  rowKey={(r) => r.keyword}
                  loading={loading}
                  columns={topColumns as any}
                  dataSource={topKeywords.filter(k => !excluded.some(e => e.word?.toLowerCase() === k.keyword?.toLowerCase()))}
                  pagination={{ pageSize: 20 }}
                  size="small"
                  scroll={{ x: true }}
                />
              </Card>
            )
          },
          {
            key: 'search',
            label: 'Поиск',
            children: (
              <Card>
                <Space direction="vertical" style={{ width: '100%' }} size="middle">
                  <Space.Compact style={{ width: '100%' }}>
                    <Input placeholder="Введите ключевое слово…" value={query} onChange={(e) => setQuery(e.target.value)} onPressEnter={runSearch} />
                    <Button type="primary" onClick={runSearch} disabled={loading || !query.trim()}>Искать</Button>
                  </Space.Compact>
                  <Table
                    rowKey={(r) => r.id}
                    loading={loading}
                    columns={searchColumns as any}
                    dataSource={results}
                    pagination={{ pageSize: 20 }}
                    size="small"
                    scroll={{ x: true }}
                  />
                </Space>
              </Card>
            )
          },
          {
            key: 'exclusions',
            label: 'Исключения',
            children: (
              <Card>
                {adminError && <Typography.Text type="danger">{adminError}</Typography.Text>}
                <Space.Compact style={{ width: '100%', marginBottom: 8 }}>
                  <Input placeholder="Добавить слово в исключения…" value={newExWord} onChange={(e) => setNewExWord(e.target.value)} />
                  <Button onClick={addExclusion} type="primary">Добавить</Button>
                </Space.Compact>
                <Table
                  rowKey={(r) => r.id}
                  columns={exclColumns as any}
                  dataSource={excluded}
                  pagination={{ pageSize: 20 }}
                  size="small"
                  scroll={{ x: true }}
                />
              </Card>
            )
          },
          {
            key: 'prompt',
            label: 'Промпт',
            children: (
              <Card>
                <Typography.Paragraph type="secondary">Системный промпт извлечения ключевых слов. Изменения применяются немедленно. Оставьте пустым, чтобы использовать дефолт.</Typography.Paragraph>
                {!promptText.trim() && (
                  <Alert style={{ marginBottom: 8 }} showIcon type="warning" message="Пустой промпт: будет использован дефолтный текст извлечения." />
                )}
                <Input.TextArea rows={8} value={promptText} onChange={(e) => setPromptText(e.target.value)} style={{ width: '100%' }} />
                <Space style={{ marginTop: 8 }}>
                  <Button type="primary" onClick={savePrompt} loading={savingPrompt}>Сохранить промпт</Button>
                  <Button onClick={loadAdminData}>Обновить данные</Button>
                  <Button onClick={() => setPromptText('')}>Сбросить на дефолт</Button>
                </Space>
              </Card>
            )
          },
          {
            key: 'test',
            label: 'Тест',
            children: (
              <Card>
                <Input.TextArea rows={4} value={testText} onChange={(e) => setTestText(e.target.value)} placeholder="Введите текст для тестового извлечения ключевых слов…" />
                <div style={{ marginTop: 8 }}>
                  <Button type="primary" onClick={testExtraction} loading={testing} disabled={!testText.trim()}>Тестировать</Button>
                </div>
                <Table
                  style={{ marginTop: 8 }}
                  rowKey={(_, idx) => String(idx)}
                  columns={testColumns as any}
                  dataSource={testKeywords || []}
                  pagination={{ pageSize: 20 }}
                  size="small"
                  scroll={{ x: true }}
                />
              </Card>
            )
          }
        ]}
      />
    </div>
  );
};

export default Keywords;


